// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address actor, uint256 id) public {
        vm.assume(actor != address(0));
        // No tokens have ever been minted in this fresh contract, so the stored
        // balance of any (actor, id) pair is zero; the reference contract reports
        // the stored balance, hence 0 for every admissible input.
        assertTrue(c.balanceOf(actor, id) == 0);
    }
}
